<div class="page-heading"><div><span class="eyebrow">Tableau noir</span><h1>Tactique</h1><p>Glissez les joueurs sur le terrain ou touchez un joueur puis un emplacement.</p></div><button class="btn btn--primary" form="tactics-form">Enregistrer la tactique</button></div>
<form method="post" action="/saves/<?= (int)$context->saveId() ?>/tactics" id="tactics-form"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="lineup" id="lineup-input"><input type="hidden" name="substitutes" id="substitutes-input">
<div class="tactics-layout"><section class="panel tactics-board-panel"><div class="panel__body"><div class="pitch" id="tactics-pitch" aria-label="Terrain tactique"><div class="pitch__lines"></div></div><div class="tactics-legend"><span><i class="dot dot--green"></i>Titulaire</span><span>Faites glisser pour permuter</span></div></div></section>
<aside class="tactics-sidebar"><section class="panel"><div class="panel__header"><h2>Structure</h2></div><div class="panel__body form-grid form-grid--two"><label class="field"><span>Formation</span><select name="formation" id="formation-select"><?php foreach ($formations as $name=>$slots): ?><option value="<?= e($name) ?>" <?= $tactic['formation']===$name?'selected':'' ?>><?= e($name) ?></option><?php endforeach; ?></select></label><label class="field"><span>Mentalité</span><select name="mentality"><?php foreach (['very_defensive'=>'Très défensive','defensive'=>'Défensive','balanced'=>'Équilibrée','attacking'=>'Offensive','very_attacking'=>'Très offensive'] as $key=>$label): ?><option value="<?= $key ?>" <?= $tactic['mentality']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="field"><span>Style</span><select name="playing_style"><?php foreach (['mixed'=>'Mixte','possession'=>'Possession','direct'=>'Jeu direct','counter'=>'Contre-attaque','wings'=>'Jeu sur les ailes','long_ball'=>'Jeu long'] as $key=>$label): ?><option value="<?= $key ?>" <?= $tactic['playing_style']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="field"><span>Pressing</span><select name="pressing"><?php foreach (['low'=>'Faible','medium'=>'Moyen','high'=>'Élevé'] as $key=>$label): ?><option value="<?= $key ?>" <?= $tactic['pressing']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="field"><span>Ligne défensive</span><select name="defensive_line"><?php foreach (['deep'=>'Bas','normal'=>'Normale','high'=>'Haute'] as $key=>$label): ?><option value="<?= $key ?>" <?= $tactic['defensive_line']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="field"><span>Tempo</span><select name="tempo"><?php foreach (['slow'=>'Lent','normal'=>'Normal','fast'=>'Rapide'] as $key=>$label): ?><option value="<?= $key ?>" <?= $tactic['tempo']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="field"><span>Largeur</span><select name="width"><?php foreach (['narrow'=>'Étroit','normal'=>'Normal','wide'=>'Large'] as $key=>$label): ?><option value="<?= $key ?>" <?= $tactic['width']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label></div></section>
<section class="panel"><div class="panel__header"><h2>Responsabilités</h2></div><div class="panel__body form-grid"><?php foreach (['captain_player_id'=>'Capitaine','penalty_taker_id'=>'Penalties','free_kick_taker_id'=>'Coups francs'] as $name=>$label): ?><label class="field"><span><?= $label ?></span><select name="<?= $name ?>"><?php foreach ($players as $player): ?><option value="<?= (int)$player['id'] ?>" <?= (int)$tactic[$name]===(int)$player['id']?'selected':'' ?>><?= e($player['first_name'].' '.$player['last_name']) ?></option><?php endforeach; ?></select></label><?php endforeach; ?></div></section></aside>
<section class="panel squad-picker"><div class="panel__header"><h2>Remplaçants <small>(7 maximum)</small></h2></div><div class="panel__body drop-list" id="substitutes-list" data-drop-zone="substitutes"></div></section>
<section class="panel squad-picker"><div class="panel__header"><h2>Joueurs disponibles</h2><input type="search" placeholder="Filtrer…" data-player-filter></div><div class="panel__body drop-list" id="available-players" data-drop-zone="available"></div></section></div>
<div id="tactics-data" data-tactic="<?= e(json_encode($tactic,JSON_HEX_APOS|JSON_HEX_QUOT)) ?>" data-players="<?= e(json_encode($playerData,JSON_HEX_APOS|JSON_HEX_QUOT)) ?>" data-formations="<?= e(json_encode($formations,JSON_HEX_APOS|JSON_HEX_QUOT)) ?>"></div>
</form>
